<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { RefreshRight, Search, View } from '@element-plus/icons-vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import request, { apiRequest } from '../api/request';
interface Review{id:string;orderNo:string;orderType:string;tenant:{name:string};targetPlan?:{name:string};addon?:{name:string};addonQuantity:number;amountCents:number;status:string;requestedByName:string;requestedAt:string;paymentProofs:Array<{paymentReference?:string;paidBy?:string}>;financeReviews:Array<{reviewerName:string;note?:string;createdAt:string}>}
const items=ref<Review[]>([]),total=ref(0),loading=ref(false),reviewing=ref('');
const query=reactive({status:'PENDING_REVIEW',orderType:'',keyword:'',page:1,pageSize:20});
const statusText:Record<string,string>={PENDING_REVIEW:'待审核',APPROVED:'已通过',REJECTED:'已驳回'},typeText:Record<string,string>={UPGRADE:'升级',RENEW:'续费',EXPANSION:'扩容'};
const statusType=(s:string)=>s==='APPROVED'?'success':s==='REJECTED'?'danger':'warning';const money=(v:number)=>`¥${(v/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}`;const time=(v?:string)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'-';
async function load(){loading.value=true;try{const data=await apiRequest<{items:Review[];total:number}>({url:'/api/subscriptions/upgrade-requests',method:'GET',params:{...query,status:query.status||undefined,orderType:query.orderType||undefined,keyword:query.keyword.trim()||undefined}});items.value=data.items;total.value=data.total}finally{loading.value=false}}
async function preview(row:Review){const response=await request.get(`/api/subscriptions/upgrade-requests/${row.id}/voucher`,{responseType:'blob'});const url=URL.createObjectURL(response.data);window.open(url,'_blank','noopener,noreferrer');window.setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function review(row:Review,decision:'APPROVED'|'REJECTED'){let note='';try{const result=await ElMessageBox.prompt(decision==='APPROVED'?'确认付款无误并自动开通对应权益？':'请填写驳回原因。',decision==='APPROVED'?'通过财务审核':'驳回订单',{confirmButtonText:decision==='APPROVED'?'通过并开通':'确认驳回',cancelButtonText:'取消',inputPlaceholder:decision==='APPROVED'?'审核备注（可选）':'请输入驳回原因',inputValidator:v=>decision==='REJECTED'&&!v.trim()?'驳回时必须填写原因':true,type:decision==='APPROVED'?'success':'warning'});note=result.value}catch{return}reviewing.value=row.id;try{await apiRequest({url:`/api/subscriptions/upgrade-requests/${row.id}/review`,method:'POST',data:{decision,note}});ElMessage.success(decision==='APPROVED'?'审核通过，权益已自动开通':'订单已驳回');await load()}finally{reviewing.value=''}}
onMounted(load);
</script>
<template><div><div class="page-actions"><div><h1 class="page-title">财务审核</h1><p class="page-description">审核套餐升级、续费和扩容订单；通过后系统自动发放权益并记录变更流水</p></div><el-button :icon="RefreshRight" @click="load">刷新</el-button></div><section class="table-panel"><div class="toolbar"><el-input v-model="query.keyword" clearable :prefix-icon="Search" placeholder="搜索订单号、租户或申请人" @keyup.enter="query.page=1;load()"/><el-select v-model="query.orderType" clearable placeholder="全部订单类型" @change="query.page=1;load()"><el-option label="套餐升级" value="UPGRADE"/><el-option label="续费" value="RENEW"/><el-option label="扩容" value="EXPANSION"/></el-select><el-select v-model="query.status" clearable placeholder="全部状态" @change="query.page=1;load()"><el-option label="待审核" value="PENDING_REVIEW"/><el-option label="已通过" value="APPROVED"/><el-option label="已驳回" value="REJECTED"/></el-select><el-button @click="query.page=1;load()">查询</el-button></div><el-table v-loading="loading" :data="items" empty-text="暂无订单"><el-table-column label="订单" min-width="210"><template #default="{row}"><div class="primary"><b>{{row.orderNo}}</b><span>{{row.tenant.name}} · {{row.requestedByName}}</span></div></template></el-table-column><el-table-column label="类型" width="100"><template #default="{row}"><el-tag effect="plain">{{typeText[row.orderType]}}</el-tag></template></el-table-column><el-table-column label="订单内容" min-width="180"><template #default="{row}">{{row.targetPlan?.name||row.addon?.name}}<span v-if="row.orderType==='EXPANSION'"> × {{row.addonQuantity}}</span></template></el-table-column><el-table-column label="金额" width="120"><template #default="{row}"><strong>{{money(row.amountCents)}}</strong></template></el-table-column><el-table-column label="凭证" width="120"><template #default="{row}"><el-button v-if="row.paymentProofs?.length" link type="primary" :icon="View" @click="preview(row)">查看凭证</el-button><span v-else>零元订单</span></template></el-table-column><el-table-column label="付款信息" min-width="150"><template #default="{row}"><div class="primary"><span>{{row.paymentProofs?.[0]?.paidBy||'未填写付款人'}}</span><span>{{row.paymentProofs?.[0]?.paymentReference||'未填写流水号'}}</span></div></template></el-table-column><el-table-column label="提交时间" min-width="170"><template #default="{row}">{{time(row.requestedAt)}}</template></el-table-column><el-table-column label="状态" width="105"><template #default="{row}"><el-tag :type="statusType(row.status)">{{statusText[row.status]}}</el-tag></template></el-table-column><el-table-column label="审核信息" min-width="190"><template #default="{row}"><div v-if="row.financeReviews?.length" class="primary"><b>{{row.financeReviews[0].reviewerName}}</b><span>{{time(row.financeReviews[0].createdAt)}} · {{row.financeReviews[0].note||'无备注'}}</span></div><span v-else>-</span></template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><template v-if="row.status==='PENDING_REVIEW'"><el-button link type="success" :loading="reviewing===row.id" @click="review(row,'APPROVED')">通过</el-button><el-button link type="danger" :disabled="reviewing===row.id" @click="review(row,'REJECTED')">驳回</el-button></template><span v-else>已完成</span></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="query.page" v-model:page-size="query.pageSize" layout="total, prev, pager, next" :total="total" @current-change="load"/></div></section></div></template>
<style scoped>.toolbar{display:grid;grid-template-columns:minmax(260px,1fr) 160px 150px auto;gap:12px;margin-bottom:18px}.primary{display:grid;gap:5px}.primary span{color:#8795a9;font-size:12px}.pagination{display:flex;justify-content:flex-end;margin-top:18px}@media(max-width:850px){.toolbar{grid-template-columns:1fr 1fr}.toolbar>*:first-child{grid-column:1/-1}}</style>
